  "prediction_basis_card_ids": ["C18", "C51", "C01", "C128"],
  "claims": [
    {
      "claim": "The query is a captopril-like thiol ACE inhibitor with a 4-phenylthio substituent; the closest L4 absorption record shows a captopril S-benzoyl thioester prodrug was well absorbed (>70%) from all GI sites, supporting that this proline-thiol scaffold can achieve high intestinal absorption.",
      "card_ids": ["C128"]
    },
    {
      "claim": "The only captopril absorption value in L4 (3.3% from rat gastric loop in 12 min) is site- and time-limited and does not measure total oral F; it is not affirmative evidence for F <20%.",
      "card_ids": ["C118"]
    },
    {
      "claim": "Enalaprilat low intestinal permeability in rat jejunum and dog lower intestine is from a dicarboxylic ACE inhibitor active acid, not the query's monocarboxylic thiol/phenylthio structure, so it has low transferability and does not overturn the high prediction.",
      "card_ids": ["C133", "C137"]
    },
    {
      "claim": "Prior direct F measurements for close small-acid and phenylthio-containing analogs remain above threshold: pidotimod 42–44%, fenbendazole 27.1 ± 10.8%, 4-phenylbutyrate 78%, ampicillin 29%, and maraviroc 24–33%.",
      "card_ids": ["C18", "C51", "C01", "C11", "C16"]
    },
    {
      "claim": "The near-threshold perindoprilat value (19 ± 7%) is from a prodrug-metabolite context and is not directly transferable to the query's free-acid thiol structure.",
      "card_ids": ["C13", "C39"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C118", "C128", "C133", "C137"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability or IV-comparison measurement for the query molecule itself.",
    "No direct intestinal permeability or fraction-absorbed measurement for the query; closest records are captopril gastric loop, captopril thioester prodrug, and enalaprilat permeability.",
    "First-pass thiol metabolism (e.g., S-methylation, disulfide formation) and possible efflux are not directly assessed.",
    "L4 solubility records are mostly for other molecules and do not quantify the query's own solubility.",
    "The normal-condition perindoprilat value (19 ± 7%) is near threshold and from a prodrug-metabolite context, limiting transferability."
  ],
  "decision_summary": "Predicted high (F ≥ 20%) because the closest small-acid and phenylthio-containing analogs have measured oral bioavailability above 20% (pidotimod 42–44%, fenbendazole 27%, PBA 78%, ampicillin 29%, maraviroc 24–33%), and L4 adds no affirmative threshold-relevant evidence for F <20%; captopril scaffold absorption is supported by >70% GI absorption of a thioester prodrug, while the low captopril gastric-loop and enalaprilat permeability records are site-specific or poorly transferable."
}

